(() => { const baseHeaders = {"accept":"application/json"}; const requestDefaults = {"method":"POST","headers":{"accept":"application/json","content-type":"application/json"}}; return (async (payload, { fetch, meta }) => {
    function identity(value) { return value; }
    const formatter = { format(value) { return identity(value); } };
    const body = [payload.body].map(function keep(value) { return formatter.format(value); })[0];
    try {
        const response = await fetch("https://api.example.com/send", {
            method: requestDefaults.method,
            headers: { ...requestDefaults.headers, "idempotency-key": meta.id },
            body: JSON.stringify({ ...payload, body }),
        });
        if (!response.ok)
            throw new Error(`provider ${response.status}`);
        return { providerId: (await response.json()).id };
    }
    catch (error) {
        throw error;
    }
}); })()
